// ------------------------------------------------------------------------ decode helpers

private fun convertMesg(mesg: Mesg, applyTypes: Boolean): FitMessage {
    val fields = js("({})")
    for (field in mesg.fieldList) {
        if (!field.hasValues) continue
        // The active subfield decides both the name and the meaning: `event.data` is
        // `gearChangeData` on a rear_gear_change event, and reading it as anything else
        // would give a number under the wrong interpretation.
        val profileFieldName = field.nameOf(SubFieldSelector.Active, mesg)
        val typeName = ProfileNames.typeOf(mesg.globalMesgNum.toInt(), profileFieldName)
        val values = List(field.numValues) {
            mesg.getFieldValue(field.fieldNum, it, SubFieldSelector.Active)
        }
        val key = if (field.fieldName == UNKNOWN_FIELD) "field${field.fieldNum}" else jsName(profileFieldName)
        fields[key] = jsValues(values, typeName, applyTypes)
    }

    val developerFields = js("({})")
    for (field in mesg.developerFieldList) {
        if (!field.hasValues) continue
        val values = List(field.numValues) { field.getValue(it) }
        developerFields[jsName(field.fieldName)] = jsValues(values, null, applyTypes)
    }

    val out = js("({})")
    out.name = jsName(mesg.mesgName)
    out.num = mesg.globalMesgNum.toInt()
    out.index = mesg.decoderMesgIndex
    out.fields = fields
    out.developerFields = developerFields
    return out.unsafeCast<FitMessage>()
}

/** One value on its own, several as an array — the shape `@garmin/fitsdk` produces. */
private fun jsValues(values: List<Any?>, typeName: String?, applyTypes: Boolean): Any? =
    if (values.size == 1) {
        jsValue(values[0], typeName, applyTypes)
    } else {
        values.map { jsValue(it, typeName, applyTypes) }.toTypedArray()
    }

private fun jsValue(value: Any?, typeName: String?, applyTypes: Boolean): Any? {
    if (value == null) return null
    if (value is String) return value

    // Deliberately not `value is Double` and friends: on the js target Byte, Short, Int,
    // Float and Double are all one JS number, so those checks do not distinguish. The
    // boxed unsigned types are real objects there, which is why this goes through
    // FitValues rather than a cast.
    val number = FitValues.toDouble(value)
    if (number.isNaN()) return value.toString()

    if (!applyTypes || typeName == null) return number

    when (typeName) {
        // A date_time is a count of seconds, not a named value, and its profile entries
        // (`min`) name a threshold rather than an instant.
        "date_time", "local_date_time" -> {
            val instant = FitDateTime.toInstant(number.toLong().toUInt()) ?: return number
            return jsDate(instant.toEpochMilliseconds().toDouble())
        }
        "bool" -> return number != 0.0
    }

    return ProfileNames.nameOf(typeName, number) ?: number
}

// ------------------------------------------------------------------------ encode helpers

private fun buildMesg(input: FitMesgInput): Mesg {
    val profileMesgName = profileName(input.name)
    val mesgNum = ProfileNames.mesgNumOf(profileMesgName)
        ?: throw IllegalArgumentException("no FIT message named '${input.name}'")

    val mesg = Factory.createMesg(mesgNum.toUShort())
    val fields = input.fields
    if (fields != null) {
        for (key in objectKeys(fields)) {
            val field = mesg.getField(profileName(key))
                ?: throw IllegalArgumentException("'${input.name}' has no field named '$key'")
            val typeName = ProfileNames.typeOf(mesgNum, field.fieldName)
            val value = fields.asDynamic()[key]
            if (isJsArray(value)) {
                val array = value.unsafeCast<Array<Any?>>()
                for (index in array.indices) {
                    mesg.setFieldValue(field.fieldNum, kotlinValue(array[index], typeName), index)
                }
            } else {
                mesg.setFieldValue(field.fieldNum, kotlinValue(value, typeName))
            }
        }
    }

    // Factory.createMesg carries every field the profile declares; the copy constructor
    // drops the ones left without a value, so only what the caller set is written.
    return Mesg(mesg)
}

private fun kotlinValue(value: Any?, typeName: String?): Any? {
    if (value == null) return null
    if (isJsDate(value)) {
        return FitDateTime.toTimestamp(kotlin.time.Instant.fromEpochMilliseconds(jsDateMillis(value).toLong()))
    }
    if (value is String) {
        // A profile value name where the field has one; anything else is a real string.
        if (typeName != null) ProfileNames.valueOf(typeName, value)?.let { return it }
        return value
    }
    if (value is Boolean) return if (value) 1.0 else 0.0
    return value
}

// ------------------------------------------------------------------------ small helpers

/** `PositionLat` to `positionLat`: profile spelling to the one JavaScript expects. */
private fun jsName(name: String): String =
    if (name.isEmpty()) name else name[0].lowercaseChar() + name.substring(1)

/** The inverse of [jsName]. */
private fun profileName(name: String): String =
    if (name.isEmpty()) name else name[0].uppercaseChar() + name.substring(1)

/** What [Factory] names a message or field the profile does not know. */
private const val UNKNOWN_FIELD: String = "unknown"

private fun jsDate(millis: Double): Any = js("new Date(millis)")

private fun isJsDate(value: Any?): Boolean = js("value instanceof Date").unsafeCast<Boolean>()

private fun jsDateMillis(value: Any?): Double = value.asDynamic().getTime().unsafeCast<Double>()

private fun isJsArray(value: Any?): Boolean = js("Array.isArray(value)").unsafeCast<Boolean>()

private fun objectKeys(value: Any?): Array<String> = js("Object.keys(value)").unsafeCast<Array<String>>()
